function makeChoices(seed: DailyLessonSeed) {
  return [
    { text: seed.experiment, correct: true, feedback: seed.principle },
    { text: "Trust the most confident answer without checking.", correct: false, feedback: seed.caution },
    { text: "Use private details to make the tool understand everything.", correct: false, feedback: "Only share information that the task truly needs, and keep personal information out." },
  ];
}

function makeDailyActivity(seed: DailyLessonSeed, ageIndex: number): Lesson["activity"] {
  const example = seed.examples[ageIndex];
  const choices = makeChoices(seed);
  const classifyItems = [
    [example, 0, seed.signal],
    [seed.caution, 1, seed.caution],
    [seed.experiment, 0, seed.principle],
  ].map(([text, category, why]) => ({ text, category: Number(category), why: String(why) }));
  const common = { scenario: example, prompt: `${seed.title}: ${seed.signal}` };
  switch (seed.activity) {
    case "predictor":
      return { kind: "predictor", title: `Steer the ${seed.topic} simulator`, instruction: `Try one clue, compare the pretend prediction, then change the context. ${seed.experiment}`,
        prompt: `${example} What is the likeliest next clue?`, choices,
        contextPrompt: `Change one thing: ${seed.caution} Which clue matters now?`,
        contextChoices: choices.map((choice, index) => ({ ...choice,
          text: index === 0 ? seed.signal : choice.text })),
      };
    case "model-sorter":
      return { kind: "model-sorter", title: `Train Pip's tiny ${seed.topic} model`, instruction: `Label these pretend examples, train the small model, and see what it misses.`,
        ...common, categories: ["Pattern to notice", "Needs a second look"], items: classifyItems,
        testCase: `New test: ${seed.caution}`, testExplanation: `${seed.signal} Add a more varied example, then test again.` };
    case "hallucination":
      return { kind: "hallucination", title: "Detective desk: check the claim", instruction: "Choose what needs evidence, then pick an independent way to verify it.",
        ...common, categories: ["Checkable clue", "Claim to verify"], items: classifyItems,
        choices: [
          { text: "Check the exact claim against an independent, dependable source.", correct: true, feedback: `${seed.signal} ${seed.principle}` },
          { text: "Trust it because the answer sounds complete.", correct: false, feedback: seed.caution },
          { text: "Ask another chatbot and treat a matching answer as proof.", correct: false, feedback: "Two matching generated answers are not an independent source." },
        ] };
    case "real-or-ai":
      return { kind: "real-or-ai", title: "Evidence lab: inspect the source", instruction: "Sort the observation from the claim, then identify a clue a person can check.",
        ...common, categories: ["Source clue to check", "Needs more evidence"], items: classifyItems };
    case "redactor":
      return { kind: "redactor", title: "Privacy shield: redact a pretend prompt", instruction: "Black out identifying details in this fully fictional sample before it is sent.",
        ...common, items: [
          { text: "Fictional name: Rowan Example", category: 1, why: "A person's name can identify them." },
          { text: "Made-up address: 42 Example Lane", category: 1, why: "An address reveals where someone lives." },
          { text: "Invented moon: Blue Pebble", category: 0, why: "A made-up story detail is not identifying." },
          { text: "Task: list three clues in a mystery", category: 0, why: "The task can be explained without personal information." },
        ] };
    case "prompt-fixer":
      return { kind: "prompt-fixer", title: `Prompt workshop: improve ${seed.topic}`, instruction: `Build a safe, clear prompt. ${seed.experiment}`,
        ...common, fields: ["goal", "context", "format", "limits"] };
    case "ai-sorter":
      return { kind: "ai-sorter", title: "Choose the right lane for AI", instruction: "Sort these fictional activities by risk, reversibility, and adult help.",
        ...common, categories: ["Okay with family rules", "Ask an adult first", "Do not use AI"],
        items: [
          { text: `Try a reversible practice activity: ${example}`, category: 0, why: "It is a bounded simulation a person can inspect." },
          { text: "A real health, money, or safety decision", category: 1, why: "A qualified person or trusted adult should help with high-stakes choices." },
          { text: "Send a password, private photo, or secret code", category: 2, why: "Personal information and credentials should stay private." },
        ] };
    case "app-planner":
      return { kind: "app-planner", title: "Build a safe five-part idea", instruction: `Plan a tiny, fictional tool that explores ${seed.topic}, then test one edge case.`,
        ...common, fields: ["problem", "user", "screens", "main action", "safety check"] };
    case "branching":
      return { kind: "branching", title: `Choose the next move: ${seed.topic}`, instruction: "Pick a path. See what changes, then revise your choice if you want.",
        ...common, choices };
    default:
      return { kind: "branching", title: seed.title, instruction: seed.experiment, ...common, choices };
  }
}

function makeChecks(seed: DailyLessonSeed): [string, string, string, string, string][] {
  return [
    [`Which statement best describes ${seed.topic}?`, seed.principle, "An AI always understands the whole situation.", "One successful example proves the tool is safe for every task.", seed.principle],
    [`What clue should you inspect in ${seed.examples[0]}?`, seed.signal, "Only whether the result sounds smooth.", "Whether the tool says it is confident.", seed.signal],
    [`Which action tests or improves this ${seed.topic} idea?`, seed.experiment, "Keep the first result and never compare it.", "Add private details until the tool agrees.", seed.experiment],
    [`Which limit is important to remember?`, seed.caution, "A polished screen removes the need for a person.", "A tool's answer cannot affect another decision.", seed.caution],
    [`How could a learner explain this topic in their own words?`, seed.principle, "The tool has human feelings and full understanding.", "Checking is unnecessary when an answer is detailed.", seed.principle],
  ];
}

function makeDailyScripts(seed: DailyLessonSeed, ageIndex: number): [string, string, string] {
  const example = seed.examples[ageIndex];
  const scenarios = [
    [
      `Hi, I'm Pip! ${seed.principle} We can explore this with clues, pictures, and pretend examples. You do not need to know big words to spot what the tool is doing. ${seed.signal}`,
      `${example} Let's pause and notice what went into the tool and what came out. Try one small change and look at the new result. That helps us learn why an answer might change. ${seed.caution}`,
      `${seed.experiment} Tell a trusted grown-up what you noticed. A computer can help us explore, but a real person checks important choices. If anything feels wrong, stop and ask for help. You can come back tomorrow for another experiment.`,
    ],
    [
      `Pip's lab is open. ${seed.principle} Treat this example like a small experiment: notice the input, compare the result, and ask what could explain the difference. ${seed.signal}`,
      `${example} Change one part while keeping the rest steady. Compare both results and name the clue that changed. This is more useful than guessing from a confident tone. ${seed.caution}`,
      `${seed.experiment} Explain which part you would check with a reliable source or trusted adult. A helpful tool can still miss context. If something feels wrong or high-stakes, stop and get human help. Take a break and return tomorrow.`,
    ],
    [
      `Builder lab: inspect the system before trusting it. ${seed.principle} Separate the input, the model's objective, the output, and the evidence needed to evaluate that output. ${seed.signal}`,
      `${example} Hold the objective constant and vary one input. Compare the outputs, then identify an edge case the examples may not cover. A fluent result is not the same as a validated result. ${seed.caution}`,
      `${seed.experiment} State the limitation and one safe next step in your own words. People remain accountable for consequential decisions. Stop and consult a trusted adult if the context is sensitive or uncertain. A short break helps; continue whenever you are ready.`,
    ],
  ];
  return scenarios.map((scenes) => scenes.map((scene) => scene.trim()).join("~")) as [string, string, string];
}

export function dailySeedAsLessonSeed(seed: DailyLessonSeed, chapterId: Lesson["levelId"], ageIndex: number) {
  const scenarios = seed.examples;
  return {
    id: seed.id,
    levelId: chapterId,
    title: seed.title,
    topic: seed.topic,
    scenarios,
    scripts: makeDailyScripts(seed, ageIndex),
    visuals: [
      `${seed.topic}: input clue → learned pattern → possible result`,
      `Evidence to inspect: ${seed.signal}`,
      `Try the safe experiment: ${seed.experiment}`,
    ] as [string, string, string],
    action: seed.experiment,
    unsafe: seed.caution,
    takeaway: seed.principle,
    steps: [
      "Notice the input",
      "Name the pattern",
      "Change one clue",
      "Check the result",
    ] as [string, string, string, string],
    checks: makeChecks(seed),
    activity: makeDailyActivity(seed, ageIndex),
    reflect: `Explain ${seed.topic} in your own words. What clue would you check before trusting its result, and why?`,
    family: `Where might we notice ${seed.topic} in everyday life, and what would we check together?`,
  };
}
